script:
var doc = Document;
// Goal: hand the user a report file and know where the run itself was recorded.
// Files exchange lives in a per-document workspace on the machine running Revit
// (skill.md "Exchanging files"): Connector.ExportsDirectory (published outputs),
// Connector.ImportsDirectory (files the user gave you), and beside them scripts/
// and logs/ -- the audit trail of every run.

// 1. Write the file anywhere writable (temp is fine), with a name that says what it is.
var name = "howto-files-report.txt";
var src = System.IO.Path.Combine(System.IO.Path.GetTempPath(), name);
int levels = new Autodesk.Revit.DB.FilteredElementCollector(doc)
    .OfClass(typeof(Autodesk.Revit.DB.Level)).GetElementCount();
System.IO.File.WriteAllText(src, "document: " + doc.Title + "\nlevels: " + levels + "\n");

// 2. Publish it. The connector copies it into ExportsDirectory and reports one
//    entry in the response's files[]: {name, path, status: published|failed, message}.
//    A name that already exists there FAILS THAT FILE (status failed, message naming
//    overwrite_output_files) without failing the run; pass execute_script
//    { "overwrite_output_files": true } to replace it. This how-to is run with the
//    flag so re-runs overwrite the same report.
Connector.Publish(src, name);
try { System.IO.File.Delete(src); } catch { }   // the copy in exports/ is the deliverable

// 3. A file written DIRECTLY into ExportsDirectory and then published is registered
//    in place: no copy, no collision gate, `published` even if the name existed.
var direct = System.IO.Path.Combine(Connector.ExportsDirectory, "howto-files-inplace.txt");
System.IO.File.WriteAllText(direct, "written in place\n");
Connector.Publish(direct);

// 4. The audit trail: logs/ and scripts/ are siblings of exports/. Each run leaves
//    <timestamp>-<execution_id>.cs (the exact script) and .ndjson (the log, with the
//    run's status) before its response is sent -- so the previous run's pair is
//    already there. Useful when a user asks "what did you run yesterday?".
var root = System.IO.Path.GetDirectoryName(Connector.ExportsDirectory);
var logsDir = System.IO.Path.Combine(root, "logs");
var scriptsDir = System.IO.Path.Combine(root, "scripts");
int logCount = System.IO.Directory.Exists(logsDir) ? System.IO.Directory.GetFiles(logsDir, "*.ndjson").Length : 0;
int scriptCount = System.IO.Directory.Exists(scriptsDir) ? System.IO.Directory.GetFiles(scriptsDir, "*.cs").Length : 0;

// 5. Verify: both files sit in exports/. Publishing changes nothing in the model, so
//    the run carries no `mutations` report. Tell the user the path from files[], not
//    a path you typed.
return new {
  published = System.IO.File.Exists(System.IO.Path.Combine(Connector.ExportsDirectory, name)),
  inPlace = System.IO.File.Exists(direct),
  exportsDirectory = Connector.ExportsDirectory,
  importsDirectory = Connector.ImportsDirectory,
  auditLogs = logCount,
  auditScripts = scriptCount
};
